#!/usr/bin/env bash
# AI_BAND deploy — kokpit2 "Nakit hikayesi": Finansal Icgoru sag-kolondan -> bolume entegre ust AI band.
#   FRONTEND-ONLY: yalniz shells/kokpit2.html. CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
KOKF=shells/kokpit2.html
[ -f "$KOKF" ] || { echo "HATA: $KOKF yok"; exit 1; }
cp "$KOKF" "$KOKF.bak.$(date +%s)"
printf '%s' '' | base64 -d > "$KOKF"
echo "kokpit2.html satir: $(wc -l < "$KOKF")"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== ONIZLE: /api/bi/kokpit2 -> Nakit hikayesi: ustte AI band + altta iki panel =="
echo "== DONE =="
